const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const pantanal = ee.FeatureCollection("WWF/HydroSHEDS/v1/Basins/hybas_7")
        .filter(ee.Filter.eq('BASIN_ID', 4107119860)); // Pantanal basin ID
    const geometry = pantanal.geometry();

    const dateCurrent = ee.Date('2024-06-11');
    const startHistoric = '2002-07-01'; // MODIS Aqua data starts mid-2002
    const endHistoric = '2023-12-31';
    const month = 6; // June

    // 2. Data Acquisition
    const collection = ee.ImageCollection('MODIS/061/MYD14A1').select('FireMask');

    // 2a. Current day's data
    const imageCurrent = collection.filterDate(dateCurrent, dateCurrent.advance(1, 'day')).mosaic();

    // 2b. Historical data for the specified month
    const collectionHistoric = collection.filterDate(startHistoric, endHistoric)
        .filter(ee.Filter.calendarRange(month, month, 'month'));

    // 3. Processing & Calculation
    function countFirePixels(image) {
        // FireMask values 7, 8, 9 are low, nominal, and high confidence fire.
        const firePixels = image.gte(7);
        const count = firePixels.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: geometry,
            scale: 1000,
            maxPixels: 1e9
        });
        return ee.Number(count.get('FireMask'));
    }

    // Calculate fire pixels for the current day
    const fireCountCurrent = countFirePixels(imageCurrent);

    // Calculate daily fire pixels for the historical collection
    const dailyCountsHistoric = collectionHistoric.map(function(image) {
        const fires = countFirePixels(image);
        return ee.Feature(null, {'fires': fires});
    });

    // Find the maximum daily fire count in the historical period
    const maxFiresHistoric = ee.Number(dailyCountsHistoric.reduceColumns({
        reducer: ee.Reducer.max(),
        selectors: ['fires']
    }).get('max'));

    // Use evaluate to fetch results from the server
    const fireCountCurrentVal = (await ee.Number(fireCountCurrent).evaluate());
    const maxFiresHistoricVal = (await ee.Number(maxFiresHistoric).evaluate());

    // 4. Validation & Final Answer
    if (fireCountCurrentVal === null || maxFiresHistoricVal === null) {
        console.log("Calculation failed: a result was null.");
        console.log("Current Day Count:", fireCountCurrentVal);
        console.log("Historical Max Count:", maxFiresHistoricVal);
        console.log("C3");
        return;
    }

    console.log(`Pantanal Fire Detections (MODIS/Aqua)`);
    console.log(`Fires on ${dateCurrent.format('YYYY-MM-dd').getInfo()}: ${fireCountCurrentVal}`);
    console.log(`Max daily fires in any June (2002-2023): ${maxFiresHistoricVal}`);

    if (fireCountCurrentVal > maxFiresHistoricVal) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during EE initialization or execution:', e);
        console.log("D");
    }
}

initEE();
